class CartScope extends InheritedNotifier<ValueNotifier<int>> {
  const CartScope({super.key, required super.notifier, required super.child});

  // Like context.watch: registers the caller as a dependent
  static int countOf(BuildContext context) =>
      context.dependOnInheritedWidgetOfExactType<CartScope>()!.notifier!.value;

  // Like context.read: no dependency, so no rebuilds
  static ValueNotifier<int> read(BuildContext context) =>
      context.getInheritedWidgetOfExactType<CartScope>()!.notifier!;
}

