class ProductScreen extends StatelessWidget {
  const ProductScreen({super.key, required this.product});
  final Product product;

  @override
  Widget build(BuildContext context) {
    // Registers ProductScreen's element as the dependent
    final count = context.watch<CartCubit>().state;
    return Scaffold(
      appBar: AppBar(actions: [Text('Cart: $count')]),
      body: ProductDetails(product: product), // rebuilt on every change
    );
  }
}

class ProductScreen extends StatelessWidget {
  const ProductScreen({super.key, required this.product});
  final Product product;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(actions: [
        // BlocBuilder's own State listens and calls setState
        BlocBuilder<CartCubit, int>(
          builder: (context, count) => Text('Cart: $count'),
        ),
      ]),
      body: ProductDetails(product: product), // built once
    );
  }
}
